// Generates src/defaultExercises.ts from assets/exercises/<slug>/README.md and the
// images next to each README. Edit the Markdown, then run `npm run exercises`.
// `--check` only verifies the generated file is up to date (used by `npm run build`).
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const ASSETS = join(ROOT, 'assets/exercises');
const OUT = join(ROOT, 'src/defaultExercises.ts');
const IMAGE_BASE = 'https://raw.githubusercontent.com/theohogberg/obsidian-exercise-plugin/main/assets/exercises/';
const IMAGE_EXT = /\.(jpe?g|png|gif|webp)$/i;

// Read the allowed values from types.ts so they're defined in one place
const types = readFileSync(join(ROOT, 'src/types.ts'), 'utf8');
const constList = name => {
  const m = types.match(new RegExp(`${name} = \\[([^\\]]*)\\]`));
  if (!m) throw new Error(`${name} not found in src/types.ts`);
  return [...m[1].matchAll(/'([^']+)'/g)].map(x => x[1]);
};
const MUSCLE_GROUPS = constList('MUSCLE_GROUPS');
const EQUIPMENT_TYPES = constList('EQUIPMENT_TYPES');

function parse(slug) {
  const file = join(ASSETS, slug, 'README.md');
  const text = readFileSync(file, 'utf8');
  const fail = msg => { throw new Error(`${file}: ${msg}`); };

  const fm = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!fm) fail('missing front matter');
  const meta = Object.fromEntries(fm[1].split('\n').map(line => {
    const i = line.indexOf(':');
    return [line.slice(0, i).trim(), line.slice(i + 1).trim()];
  }));
  for (const key of ['id', 'name', 'muscleGroup', 'equipment']) if (!meta[key]) fail(`front matter needs "${key}"`);
  if (!MUSCLE_GROUPS.includes(meta.muscleGroup)) fail(`muscleGroup must be one of ${MUSCLE_GROUPS.join(', ')}`);
  if (!EQUIPMENT_TYPES.includes(meta.equipment)) fail(`equipment must be one of ${EQUIPMENT_TYPES.join(', ')}`);

  const sections = {};
  for (const part of text.slice(fm[0].length).split(/^## /m).slice(1)) {
    const [heading, ...body] = part.split('\n');
    sections[heading.trim().toLowerCase()] = body.join('\n').trim();
  }
  for (const s of ['cues', 'setup', 'steps']) if (!sections[s]) fail(`missing "## ${s[0].toUpperCase()}${s.slice(1)}" section`);
  const steps = sections.steps.split('\n').map(l => l.match(/^\d+\.\s+(.*)$/)?.[1]).filter(Boolean);
  if (steps.length === 0) fail('"## Steps" needs a numbered list');

  const images = readdirSync(join(ASSETS, slug)).filter(f => IMAGE_EXT.test(f)).sort();
  return {
    id: meta.id, name: meta.name, muscleGroup: meta.muscleGroup, equipment: meta.equipment,
    notes: sections.cues.replace(/\s*\n\s*/g, ' '),
    setup: sections.setup.replace(/\s*\n\s*/g, ' '),
    steps, slug, images,
  };
}

const q = s => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

const exercises = readdirSync(ASSETS, { withFileTypes: true })
  .filter(d => d.isDirectory())
  .map(d => parse(d.name))
  .sort((a, b) => MUSCLE_GROUPS.indexOf(a.muscleGroup) - MUSCLE_GROUPS.indexOf(b.muscleGroup) || a.name.localeCompare(b.name));

const ids = new Set();
for (const e of exercises) {
  if (ids.has(e.id)) throw new Error(`duplicate id ${e.id}`);
  ids.add(e.id);
}

const out = [
  '// GENERATED by scripts/build-exercises.mjs from assets/exercises/*/README.md. Do not edit:',
  '// change the Markdown and run `npm run exercises`. Photos are from free-exercise-db',
  '// (public domain), hosted in this repo; names, cues and how-tos are our own.',
  "import { Exercise } from './types';",
  '',
  `const IMAGE_BASE = ${q(IMAGE_BASE)};`,
  '',
  "function images(slug: string, files: string[]): Exercise['media'] {",
  "  return files.map(f => ({ type: 'image' as const, src: `${IMAGE_BASE}${slug}/${f}` }));",
  '}',
  '',
  'export const DEFAULT_EXERCISES: Exercise[] = [',
  ...exercises.flatMap(e => [
    '  {',
    `    id: ${q(e.id)},`,
    `    name: ${q(e.name)},`,
    `    muscleGroup: ${q(e.muscleGroup)},`,
    `    equipment: ${q(e.equipment)},`,
    `    notes: ${q(e.notes)},`,
    `    media: images(${q(e.slug)}, [${e.images.map(q).join(', ')}]),`,
    `    setup: ${q(e.setup)},`,
    '    instructions: [',
    ...e.steps.map(s => `      ${q(s)},`),
    '    ],',
    '  },',
  ]),
  '];',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  if (readFileSync(OUT, 'utf8') !== out) {
    console.error('src/defaultExercises.ts is out of date with assets/exercises. Run `npm run exercises`.');
    process.exit(1);
  }
} else {
  writeFileSync(OUT, out);
  console.log(`Wrote ${exercises.length} exercises to src/defaultExercises.ts`);
}
